import unittest

from hourglass.rounding import round_spans
from hourglass.models import Span


class RoundSpansTests(unittest.TestCase):
    def test_rounds_to_nearest_step(self):
        result = round_spans([Span(542, 1033)], 15)
        self.assertEqual(result, ["09:00-17:15 (8h 15m)"])

    def test_halfway_rounds_up(self):
        result = round_spans([Span(67, 127)], 30)
        self.assertEqual(result, ["01:00-02:00 (1h 0m)"])

    def test_several_spans(self):
        spans = [Span(540, 600), Span(601, 721)]
        self.assertEqual(
            round_spans(spans, 5),
            ["09:00-10:00 (1h 0m)", "10:00-12:00 (2h 0m)"]
        )

    def test_bad_steps_raise(self):
        for step in (0, -15, 7, 45):
            with self.assertRaises(ValueError):
                round_spans([Span(0, 60)], step)
